# NOTE: Assertions have been autogenerated by utils/update_mca_test_checks.py
# RUN: llvm-mca -mtriple=vu -mcpu=vu0 -iterations=100 -timeline=false -resource-pressure=false < %s | FileCheck %s

# A micro instruction word is two instructions, upper and lower. The
# latencies are the measured ones of VUSchedule.td: an FMAC chain takes 4
# cycles per word, an ACC chain 1, and DIV keeps the FDIV unit for 7.

add.xyzw vf1, vf1, vf2		iadd vi4, vi4, vi3
madda.xyzw acc, vf2, vf3		div q, vf2x, vf3x

# CHECK:      Iterations:        100
# CHECK-NEXT: Instructions:      400
# CHECK-NEXT: Total Cycles:      702
# CHECK-NEXT: Total uOps:        400

# CHECK:      Dispatch Width:    2
# CHECK-NEXT: uOps Per Cycle:    0.57
# CHECK-NEXT: IPC:               0.57
# CHECK-NEXT: Block RThroughput: 7.0

# CHECK:      Instruction Info:
# CHECK-NEXT: [1]: #uOps
# CHECK-NEXT: [2]: Latency
# CHECK-NEXT: [3]: RThroughput
# CHECK-NEXT: [4]: MayLoad
# CHECK-NEXT: [5]: MayStore
# CHECK-NEXT: [6]: HasSideEffects (U)

# CHECK:      [1]    [2]    [3]    [4]    [5]    [6]    Instructions:
# CHECK-NEXT:  1      4     1.00                        add.xyzw	vf1, vf1, vf2
# CHECK-NEXT:  1      1     1.00                        iadd	vi4, vi4, vi3
# CHECK-NEXT:  1      1     1.00                        madda.xyzw	acc, vf2, vf3
# CHECK-NEXT:  1      7     7.00                        div	q, vf2x, vf3x
